        }
      }
    },
    {
      "description": "Value",
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "alphabetic",
        "fontWeight": "bold",
        "x": {
          "expr": "textX"
        },
        "y": {
          "expr": "blockTop + 44 * unit"
        },
        "fontSize": {
          "expr": "26 * unit"
        },
        "limit": {
          "expr": "textW"
        },
        "fill": {
          "expr": "valueColor"
        }
      },
      "encoding": {
        "text": {
          "field": "valueText",
          "type": "nominal"
        },
        "tooltip": [
          {
            "field": "valueText",
            "type": "nominal",
            "title": "Value"
          },
          {
            "field": "targetText",
